Translate the following GNU C++ code to Python 3.11 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define f first
#define s second
#define ll long long
#define mp make_pair
#define pb push_back

using namespace std;

double eps = 1e-9;
const int INF = 1e9+7;
const int MAXN = int (2e6+7);

int n, p, k, u[MAXN], ans = 1, mod = INF;

void dfs(int v) {
	u[v] = 1;
	int x = (k * 1ll * v) % p;
	if(!u[x])
		dfs(x);
}

int main () {
   	//freopen("input.in", "r", stdin);
   	//freopen("output.txt", "w", stdout);  

    cin >> p >> k;
    int i = 1;
    if(k == 1) {
    	i = 0;
    }
    for(; i < p; i ++) {
    	if(!u[i]) {
    		dfs(i);
    		ans = (ans * 1ll * p) % mod;
    	}
    }
    cout << ans;
    return 0;
}
</original_code>
